package engine

import (
	"fmt"
	"sort"
	"strings"

	"mcbench/constants"
)

const (
	// maxPaySources keeps the brute-force enumeration bounded. A hand is
	// never this large in practice.
	maxPaySources = 16
	// abilitySuffix marks a resource generated by a card in play, to tell it
	// apart from a card of the same name in hand.
	abilitySuffix = "(ability)"
	// abilityText names a resource ability in option text.
	abilityText = " ability"
)

// paySource is one thing that can produce resources: a hand card or a
// resource ability of a card in play.
type paySource struct {
	card     *Card
	fromHand bool
	gives    []Resource
}

func (p paySource) label() string {
	if p.fromHand {
		return p.card.Name()
	}
	return p.card.Name() + abilitySuffix
}

// Payment is a set of sources that together pay a cost.
type Payment struct {
	sources []paySource
}

// Label is a stable key, e.g. "Energy+Genius". Empty for a free payment.
func (p Payment) Label() string {
	names := make([]string, len(p.sources))
	for i, s := range p.sources {
		names[i] = s.label()
	}
	sort.Strings(names)
	return strings.Join(names, constants.SepPayJoin)
}

// Describe is the human-readable suffix for option text.
func (p Payment) Describe() string {
	if len(p.sources) == 0 {
		return ""
	}
	return ", paying: " + p.sourcesText()
}

// sourcesText lists what the payment spends, e.g. "Genius (mental,mental),
// Peter Parker ability (mental)": hand cards are discarded, abilities used.
func (p Payment) sourcesText() string {
	parts := make([]string, len(p.sources))
	for i, s := range p.sources {
		res := make([]string, len(s.gives))
		for j, r := range s.gives {
			res[j] = string(r)
		}
		name := s.card.Name()
		if !s.fromHand {
			name += abilityText
		}
		parts[i] = name + " (" + strings.Join(res, ",") + ")"
	}
	return strings.Join(parts, ", ")
}

// Option texts of the payment step.
const (
	payPrompt  = "Choose how to pay for: %s."
	cancelText = "Cancel: go back without paying"
)

// payOption offers one action whose cost can be paid in the given ways (at
// least one). With a single way, or a free cost, the option pays and applies
// at once. With several, it opens a payment decision listing each way plus a
// cancel option, so the list of actions stays short and the player can still
// change its mind; cancel (may be nil) runs when it does.
func (g *Game) payOption(key, text string, pays []Payment, apply func(Payment), cancel func()) Option {
	if len(pays) == 1 {
		p := pays[0]
		return Option{Key: key, Pay: p.Label(), Text: text + p.Describe(), do: func() { apply(p) }}
	}
	return Option{Key: key, Text: text, do: func() { g.askPayment(text, pays, apply, cancel) }}
}

func (g *Game) askPayment(text string, pays []Payment, apply func(Payment), cancel func()) {
	opts := make([]Option, 0, len(pays)+1)
	for _, p := range pays {
		opts = append(opts, Option{
			Key:  constants.PrefixPay + p.Label(),
			Text: p.sourcesText(),
			do:   func() { g.Do(func() { apply(p) }) },
		})
	}
	opts = append(opts, Option{Key: constants.KeyCancel, Text: cancelText, do: cancel})
	g.Ask(&Decision{Kind: constants.KindPayment, Prompt: fmt.Sprintf(payPrompt, text), Options: opts})
}

// Spend discards the hand cards and uses the abilities.
func (p Payment) Spend(g *Game) {
	g.LastPaid = nil
	for _, s := range p.sources {
		g.LastPaid = append(g.LastPaid, s.gives...)
	}
	for _, s := range p.sources {
		if s.fromHand {
			g.moveFromHand(s.card)
			g.S.Discard = append(g.S.Discard, s.card)
		} else {
			s.card.Face().Script.ResourceAbility.Use(g, s.card)
		}
	}
}

// paySources lists what can pay for `paying` (nil for an ability cost).
func (g *Game) paySources(exclude *Card, paying *CardDef) []paySource {
	var out []paySource
	for _, c := range g.S.Hand {
		if c == exclude || len(c.Def.Resources) == 0 {
			continue
		}
		gives := c.Def.Resources
		if c.Def.DoubleFor != "" && paying != nil && paying.Aspect == c.Def.DoubleFor {
			gives = append(append([]Resource(nil), gives...), gives...)
		}
		out = append(out, paySource{card: c, fromHand: true, gives: gives})
	}
	g.inPlay(func(c *Card) {
		sc := c.Face().Script
		if sc == nil || sc.ResourceAbility == nil {
			return
		}
		ra := sc.ResourceAbility
		if ra.Usable != nil && !ra.Usable(g, c) {
			return
		}
		gives := []Resource{ra.Gives}
		if ra.FromDiscard {
			if len(g.S.Discard) == 0 {
				return
			}
			gives = g.S.Discard[len(g.S.Discard)-1].Def.Resources
		}
		if len(gives) > 0 {
			out = append(out, paySource{card: c, gives: gives})
		}
	})
	return out
}

// covers reports whether the pooled resources pay `cost` including the
// specific `need` symbols (each need symbol counts toward cost).
func covers(pool []Resource, cost int, need []Resource) bool {
	total := cost
	if len(need) > total {
		total = len(need)
	}
	if len(pool) < total {
		return false
	}
	avail := map[Resource]int{}
	for _, r := range pool {
		avail[r]++
	}
	for _, r := range need {
		if avail[r] > 0 {
			avail[r]--
		} else if avail[Wild] > 0 {
			avail[Wild]--
		} else {
			return false
		}
	}
	return true
}

// paymentsFor lists every minimal way to pay `cost` for `card` (excluded
// from the pool; paying is the card being played, nil for an ability).
// Overpaying is never offered: removing any source from a listed payment
// would make it insufficient. Equivalent payments are deduplicated.
func (g *Game) paymentsFor(card *Card, paying *CardDef, cost int, need []Resource) []Payment {
	if cost <= 0 && len(need) == 0 {
		return []Payment{{}}
	}
	srcs := g.paySources(card, paying)
	if len(srcs) > maxPaySources {
		srcs = srcs[:maxPaySources]
	}
	var out []Payment
	seen := map[string]bool{}
	for mask := 1; mask < 1<<len(srcs); mask++ {
		p, ok := minimalPayment(srcs, mask, cost, need)
		if !ok {
			continue
		}
		if l := p.Label(); !seen[l] {
			seen[l] = true
			out = append(out, p)
		}
	}
	return out
}

// minimalPayment builds the payment for mask, or reports ok=false when it
// does not cover the cost or some strict subset already covers it.
func minimalPayment(srcs []paySource, mask, cost int, need []Resource) (Payment, bool) {
	if !covers(resourcesOf(srcs, mask), cost, need) {
		return Payment{}, false
	}
	for i := range srcs {
		if mask&(1<<i) != 0 && covers(resourcesOf(srcs, mask&^(1<<i)), cost, need) {
			return Payment{}, false
		}
	}
	var p Payment
	for i, s := range srcs {
		if mask&(1<<i) != 0 {
			p.sources = append(p.sources, s)
		}
	}
	return p, true
}

// resourcesOf pools the resources of the sources selected by mask.
func resourcesOf(srcs []paySource, mask int) []Resource {
	var pool []Resource
	for i, s := range srcs {
		if mask&(1<<i) != 0 {
			pool = append(pool, s.gives...)
		}
	}
	return pool
}

func (g *Game) moveFromHand(c *Card) {
	g.S.Hand = remove(g.S.Hand, c)
}
